<div style={{ background: "#fff", border: "1px solid #E6EBE9", borderRadius: "22px", padding: "24px", flexShrink: "0" }}><div><div style={{ fontSize: "12.5px", fontWeight: "700", marginBottom: "8px" }}>Type</div><div style={{ display: "flex", gap: "6px", flexWrap: "wrap", flexShrink: "0" }}>{(formulaire.types ?? []).map((t, tIndex) => (<button key={tIndex} type="button" onClick={t.onPick} aria-pressed={t.bg === "#16785E"} data-evenement-type="" style={{ padding: "8px 13px", borderRadius: "999px", fontSize: "12.5px", fontWeight: "700", whiteSpace: "nowrap", backgroundColor: t.bg, color: t.fg, border: `1px solid ${t.bd}`, fontFamily: "inherit", cursor: "pointer" }}>{t.label}</button>))}</div></div><div style={{ display: "flex", flexDirection: "column", gap: "12px", marginTop: "14px" }}><div style={{ flexShrink: "0" }}><div style={{ fontSize: "12.5px", fontWeight: "700", marginBottom: "6px" }}>Titre</div><input type="text" value={formulaire.titre} onChange={formulaire.onTitre} aria-label="Le titre de l’événement" data-evenement-titre="" maxLength={120} style={{ minHeight: "48px", borderRadius: "14px", border: "1.5px solid #16785E", background: "#fff", padding: "13px 14px", fontSize: "14px", lineHeight: "1.5", width: "100%", boxSizing: "border-box", font: "inherit", color: "#16211D", outline: "none" }} /></div><div style={{ flexShrink: "0" }}><div style={{ fontSize: "12.5px", fontWeight: "700", marginBottom: "6px" }}>Description</div><textarea value={formulaire.description} onChange={formulaire.onDescription} aria-label="La description de l’événement" maxLength={3000} data-evenement-description="" style={{ minHeight: "48px", borderRadius: "14px", border: "1px solid #E6EBE9", background: "#fff", padding: "13px 14px", fontSize: "14px", lineHeight: "1.5", width: "100%", boxSizing: "border-box", font: "inherit", color: "#16211D", outline: "none", resize: "vertical" }} /></div><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}><div style={{ flexShrink: "0" }}><div style={{ fontSize: "12.5px", fontWeight: "700", marginBottom: "6px" }}>Ville</div><select value={formulaire.villeId} onChange={formulaire.onVille} aria-label="La ville de l’événement" data-evenement-ville="" style={{ minHeight: "48px", borderRadius: "14px", border: "1px solid #E6EBE9", background: "#fff", padding: "13px 14px", fontSize: "14px", lineHeight: "1.5", width: "100%", boxSizing: "border-box", font: "inherit", color: "#16211D", outline: "none" }}><option value="">Choisir une ville</option>{(formulaire.villes ?? []).map((v, vIndex) => (<option key={vIndex} value={v.id}>{v.nom}</option>))}</select></div><div style={{ flexShrink: "0" }}><div style={{ fontSize: "12.5px", fontWeight: "700", marginBottom: "6px" }}>Lieu</div><input type="text" value={formulaire.lieu} onChange={formulaire.onLieu} aria-label="Le lieu" data-evenement-lieu="" maxLength={160} style={{ minHeight: "48px", borderRadius: "14px", border: "1px solid #E6EBE9", background: "#fff", padding: "13px 14px", fontSize: "14px", lineHeight: "1.5", width: "100%", boxSizing: "border-box", font: "inherit", color: "#16211D", outline: "none" }} /></div></div><div style={{ flexShrink: "0" }}><div style={{ fontSize: "12.5px", fontWeight: "700", marginBottom: "6px" }}>Adresse</div><input type="text" value={formulaire.adresse} onChange={formulaire.onAdresse} aria-label="L’adresse" data-evenement-adresse="" maxLength={400} style={{ minHeight: "48px", borderRadius: "14px", border: "1px solid #E6EBE9", background: "#fff", padding: "13px 14px", fontSize: "14px", lineHeight: "1.5", width: "100%", boxSizing: "border-box", font: "inherit", color: "#16211D", outline: "none" }} /></div><div style={{ fontSize: "12px", color: "#8A958F", marginTop: "-6px" }}>Adresse en texte libre, jamais géolocalisée.</div><div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: "12px" }}><div style={{ flexShrink: "0" }}><div style={{ fontSize: "12.5px", fontWeight: "700", marginBottom: "6px" }}>Début</div><input type="datetime-local" value={formulaire.debut} onChange={formulaire.onDebut} aria-label="Le début" data-evenement-debut="" style={{ minHeight: "48px", borderRadius: "14px", border: "1px solid #E6EBE9", background: "#fff", padding: "13px 14px", fontSize: "14px", lineHeight: "1.5", width: "100%", boxSizing: "border-box", font: "inherit", color: "#16211D", outline: "none" }} /></div><div style={{ flexShrink: "0" }}><div style={{ fontSize: "12.5px", fontWeight: "700", marginBottom: "6px" }}>Fin</div><input type="datetime-local" value={formulaire.fin} onChange={formulaire.onFin} aria-label="La fin" data-evenement-fin="" style={{ minHeight: "48px", borderRadius: "14px", border: "1px solid #E6EBE9", background: "#fff", padding: "13px 14px", fontSize: "14px", lineHeight: "1.5", width: "100%", boxSizing: "border-box", font: "inherit", color: "#16211D", outline: "none" }} /></div><div style={{ flexShrink: "0" }}><div style={{ fontSize: "12.5px", fontWeight: "700", marginBottom: "6px" }}>Capacité</div><input type="number" min={1} value={formulaire.capacite} onChange={formulaire.onCapacite} aria-label="La capacité (vide : sans limite)" data-evenement-capacite="" style={{ minHeight: "48px", borderRadius: "14px", border: "1px solid #E6EBE9", background: "#fff", padding: "13px 14px", fontSize: "14px", lineHeight: "1.5", width: "100%", boxSizing: "border-box", font: "inherit", color: "#16211D", outline: "none" }} /></div></div><div><div style={{ fontSize: "12.5px", fontWeight: "700", marginBottom: "6px" }}>Réservé à un réseau</div><select value={formulaire.reseauId} onChange={formulaire.onReseau} disabled={formulaire.reseauFige} aria-label="Réservé à un réseau" data-evenement-reseau="" style={{ height: "48px", borderRadius: "14px", border: "1px solid #E6EBE9", padding: "0 14px", display: "flex", alignItems: "center", justifyContent: "space-between", width: "100%", font: "inherit", fontSize: "14px", fontWeight: "600", color: "#16211D", background: "#fff", outline: "none" }}><option value="">Ouvert à tous</option>{(formulaire.reseaux ?? []).map((r, rIndex) => (<option key={rIndex} value={r.id}>{r.nom}</option>))}</select></div><label data-evenement-couverture="" style={{ height: "90px", borderRadius: "16px", border: "1.5px dashed #CBD5D1", display: "flex", alignItems: "center", justifyContent: "center", gap: "8px", fontSize: "13px", fontWeight: "700", color: "#5D6B66", cursor: "pointer" }}><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#5D6B66" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M3 4h18v16H3zM8.5 11a1.6 1.6 0 1 0 0-3.2 1.6 1.6 0 0 0 0 3.2zM21 16l-5-5-9 9" /></svg>{formulaire.couverture === "" ? "Ajouter une couverture" : formulaire.couverture}<input type="file" accept="image/*" onChange={formulaire.onCouverture} style={{ display: "none" }} /></label></div>{formulaire.echec === "" ? null : (<p role="alert" data-evenement-echec="" style={{ margin: "0", fontSize: "12.5px", fontWeight: "700", color: "#B4581F" }}>{formulaire.echec}</p>)}<button type="button" onClick={formulaire.onPublier} disabled={formulaire.bloque} data-evenement-publier="" style={{ padding: "0 18px", borderRadius: "14px", background: "#16785E", color: "#fff", border: "none", font: "inherit", fontSize: "13.5px", fontWeight: "700", display: "flex", alignItems: "center", justifyContent: "center", gap: "8px", whiteSpace: "nowrap", flexShrink: "0", width: "100%", marginTop: "16px", height: "50px", cursor: "pointer", opacity: formulaire.bloque ? ".55" : "1" }}>{formulaire.modification ? "Enregistrer" : "Publier l’événement"}</button></div>
